from pathlib import Path

path = Path('app/src/main/java/com/getfunds/lgr100connector/MainActivity.java')
s = path.read_text(encoding='utf-8')


def replace_once(old: str, new: str, label: str):
    global s
    if old not in s:
        raise SystemExit(f'V1.0 patch failed: could not find {label}')
    s = s.replace(old, new, 1)

# Version labels after V0.9 has run.
s = s.replace('LG 360 VR Connector V0.9', 'LG 360 VR Connector V1.0')
s = s.replace('=== V0.9 WAKE SEQUENCE START ===', '=== V1.0 WAKE SEQUENCE START ===')
s = s.replace('=== V0.9 WAKE SEQUENCE COMPLETE ===', '=== V1.0 WAKE SEQUENCE COMPLETE ===')
s = s.replace(
    'Uses OpenHMD float IMU format with corrected physical axes: yaw=GY, pitch=GX, roll=GZ',
    'VR gaming screen: proper stereo alignment, head tracking, live size/depth/position controls and rotation-aware capture')

# VR screen state.
replace_once(
'''    private Presentation presentation;\n    private final Handler handler = new Handler(Looper.getMainLooper());''',
'''    private Presentation presentation;\n    private TextView vrScreenStatus;\n    private final Handler handler = new Handler(Looper.getMainLooper());\n\n    // Virtual-screen tuning. Values are normalized to each rotated eye viewport.\n    private volatile float vrScreenScale = 0.80f;\n    private volatile float vrStereoDepth = 0.012f;\n    private volatile float vrOffsetX = 0.0f;\n    private volatile float vrOffsetY = 0.0f;\n    private volatile boolean vrWorldLocked = true;''',
'VR screen fields')

# Replace the simple share row with gaming controls and a status line.
replace_once(
'''        LinearLayout row5 = row();\n        Button share = button("Share phone screen");\n        share.setOnClickListener(v -> requestScreenShare());\n        row5.addView(share, weighted());\n        Button stopShare = button("Stop screen share");\n        stopShare.setOnClickListener(v -> stopScreenShare());\n        row5.addView(stopShare, weighted());\n        root.addView(row5);\n\n        sensorStatus = new TextView(this);''',
'''        LinearLayout row5 = row();\n        Button share = button("Start VR game screen");\n        share.setOnClickListener(v -> requestScreenShare());\n        row5.addView(share, weighted());\n        Button stopShare = button("Stop VR screen");\n        stopShare.setOnClickListener(v -> stopScreenShare());\n        row5.addView(stopShare, weighted());\n        Button recenterVr = button("Recenter VR");\n        recenterVr.setOnClickListener(v -> recenterVrScreen());\n        row5.addView(recenterVr, weighted());\n        root.addView(row5);\n\n        LinearLayout row6 = row();\n        Button smaller = button("Screen -");\n        smaller.setOnClickListener(v -> adjustVrScale(-0.04f));\n        row6.addView(smaller, weighted());\n        Button larger = button("Screen +");\n        larger.setOnClickListener(v -> adjustVrScale(0.04f));\n        row6.addView(larger, weighted());\n        Button farther = button("Depth -");\n        farther.setOnClickListener(v -> adjustVrDepth(-0.003f));\n        row6.addView(farther, weighted());\n        Button nearer = button("Depth +");\n        nearer.setOnClickListener(v -> adjustVrDepth(0.003f));\n        row6.addView(nearer, weighted());\n        root.addView(row6);\n\n        LinearLayout row7 = row();\n        Button moveLeft = button("← Screen");\n        moveLeft.setOnClickListener(v -> adjustVrOffset(-0.025f, 0));\n        row7.addView(moveLeft, weighted());\n        Button moveRight = button("Screen →");\n        moveRight.setOnClickListener(v -> adjustVrOffset(0.025f, 0));\n        row7.addView(moveRight, weighted());\n        Button moveUp = button("↑ Screen");\n        moveUp.setOnClickListener(v -> adjustVrOffset(0, -0.025f));\n        row7.addView(moveUp, weighted());\n        Button moveDown = button("↓ Screen");\n        moveDown.setOnClickListener(v -> adjustVrOffset(0, 0.025f));\n        row7.addView(moveDown, weighted());\n        root.addView(row7);\n\n        LinearLayout row8 = row();\n        Button lockMode = button("Toggle head/world lock");\n        lockMode.setOnClickListener(v -> toggleVrLock());\n        row8.addView(lockMode, weighted());\n        Button resetVr = button("Reset VR tuning");\n        resetVr.setOnClickListener(v -> resetVrTuning());\n        row8.addView(resetVr, weighted());\n        root.addView(row8);\n\n        vrScreenStatus = new TextView(this);\n        vrScreenStatus.setTextSize(11);\n        vrScreenStatus.setTextColor(Color.BLACK);\n        vrScreenStatus.setPadding(dp(6), dp(4), dp(6), dp(6));\n        root.addView(vrScreenStatus);\n        updateVrScreenStatus();\n\n        sensorStatus = new TextView(this);''',
'VR gaming UI')

# Insert VR tuning helpers before screen-share request.
replace_once(
'''    private void requestScreenShare() {''',
'''    private void adjustVrScale(float delta) {\n        vrScreenScale = (float) clamp(vrScreenScale + delta, 0.48, 0.96);\n        updateVrScreenStatus();\n    }\n\n    private void adjustVrDepth(float delta) {\n        vrStereoDepth = (float) clamp(vrStereoDepth + delta, 0.0, 0.045);\n        updateVrScreenStatus();\n    }\n\n    private void adjustVrOffset(float dx, float dy) {\n        vrOffsetX = (float) clamp(vrOffsetX + dx, -0.25, 0.25);\n        vrOffsetY = (float) clamp(vrOffsetY + dy, -0.25, 0.25);\n        updateVrScreenStatus();\n    }\n\n    private void toggleVrLock() {\n        vrWorldLocked = !vrWorldLocked;\n        resetOrientation();\n        updateVrScreenStatus();\n        append("VR screen mode: " + (vrWorldLocked ? "WORLD LOCKED (head tracking moves view)" : "HEAD LOCKED (gaming comfort)"));\n    }\n\n    private void recenterVrScreen() {\n        resetOrientation();\n        vrOffsetX = 0.0f;\n        vrOffsetY = 0.0f;\n        updateVrScreenStatus();\n        append("VR screen recentered");\n    }\n\n    private void resetVrTuning() {\n        vrScreenScale = 0.80f;\n        vrStereoDepth = 0.012f;\n        vrOffsetX = 0.0f;\n        vrOffsetY = 0.0f;\n        vrWorldLocked = true;\n        resetOrientation();\n        updateVrScreenStatus();\n        append("VR screen tuning reset to defaults");\n    }\n\n    private void updateVrScreenStatus() {\n        if (vrScreenStatus == null) return;\n        String text = String.format(Locale.US,\n                "VR SCREEN | size %.0f%% | stereo depth %.1f%% | X %+.0f%% | Y %+.0f%% | %s",\n                vrScreenScale * 100f, vrStereoDepth * 100f, vrOffsetX * 100f, vrOffsetY * 100f,\n                vrWorldLocked ? "WORLD LOCKED" : "HEAD LOCKED");\n        runOnUiThread(() -> vrScreenStatus.setText(text));\n    }\n\n    private void requestScreenShare() {''',
'VR tuning helpers')

