s = s.replace('append("Screen capture starting at " + captureW + "x" + captureH);',
              'append("VR gaming capture starting at " + captureW + "x" + captureH + "; auto-resizes when phone rotates");')

# Make presentation/view non-static so it can consume calibrated orientation and live tuning fields.
replace_once(
'''    private static class ScreenMirrorPresentation extends Presentation {\n        ScreenMirrorPresentation(Context outerContext, Display display) { super(outerContext, display); }\n        @Override protected void onCreate(Bundle savedInstanceState) {\n            super.onCreate(savedInstanceState);\n            getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);\n            setContentView(new ScreenMirrorView(getContext()));\n        }\n    }''',
'''    private class ScreenMirrorPresentation extends Presentation {\n        ScreenMirrorPresentation(Context outerContext, Display display) { super(outerContext, display); }\n        @Override protected void onCreate(Bundle savedInstanceState) {\n            super.onCreate(savedInstanceState);\n            getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);\n            setContentView(new ScreenMirrorView(getContext()));\n        }\n    }''',
'mirror presentation')

# Replace the old fitted duplicate with a tracked, stereo-aligned virtual-screen renderer.
old_view = '''    private static class ScreenMirrorView extends View {\n        private final Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG | Paint.FILTER_BITMAP_FLAG);\n        private final RectF dst = new RectF();\n        ScreenMirrorView(Context context) { super(context); setKeepScreenOn(true); }\n\n        @Override protected void onDraw(Canvas c) {\n            int w = getWidth(), h = getHeight();\n            float mid = w / 2f;\n            c.drawColor(Color.BLACK);\n            boolean left = drawMirrorEye(c, 0, mid, h, 90f);\n            boolean right = drawMirrorEye(c, mid, w, h, -90f);\n\n            if (!left && !right) {\n                paint.setColor(Color.WHITE);\n                paint.setTextSize(30);\n                paint.setTextAlign(Paint.Align.CENTER);\n                c.drawText("Waiting for phone screen...", w / 2f, h / 2f, paint);\n            }\n            postInvalidateDelayed(33);\n        }\n\n        private boolean drawMirrorEye(Canvas c, float left, float right, float height, float rotation) {\n            float cx = (left + right) / 2f;\n            float cy = height / 2f;\n            float eyeW = right - left;\n            c.save();\n            c.clipRect(left, 0, right, height);\n            c.rotate(rotation, cx, cy);\n            float boxW = height * 0.78f;\n            float boxH = eyeW * 0.78f;\n            dst.set(cx - boxW / 2f, cy - boxH / 2f, cx + boxW / 2f, cy + boxH / 2f);\n            boolean drawn = ScreenCaptureService.drawLatestFrame(c, dst, paint);\n            c.restore();\n            return drawn;\n        }\n    }'''
new_view = '''    private class ScreenMirrorView extends View {\n        private final Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG | Paint.FILTER_BITMAP_FLAG);\n        private final Paint framePaint = new Paint(Paint.ANTI_ALIAS_FLAG);\n        private final RectF dst = new RectF();\n        ScreenMirrorView(Context context) {\n            super(context);\n            setKeepScreenOn(true);\n            framePaint.setStyle(Paint.Style.STROKE);\n            framePaint.setStrokeWidth(2f);\n            framePaint.setColor(Color.rgb(55, 75, 90));\n        }\n\n        @Override protected void onDraw(Canvas c) {\n            int w = getWidth(), h = getHeight();\n            float mid = w / 2f;\n            c.drawColor(Color.BLACK);\n            boolean left = drawMirrorEye(c, 0, mid, h, 90f, true);\n            boolean right = drawMirrorEye(c, mid, w, h, -90f, false);\n\n            if (!left && !right) {\n                paint.setColor(Color.WHITE);\n                paint.setTextSize(30);\n                paint.setTextAlign(Paint.Align.CENTER);\n                c.drawText("Waiting for phone screen...", w / 2f, h / 2f, paint);\n            }\n            // 60 Hz target. MediaProjection may deliver fewer frames, but headset motion remains smooth.\n            postInvalidateDelayed(16);\n        }\n\n        private boolean drawMirrorEye(Canvas c, float left, float right, float height, float rotation, boolean leftEye) {\n            float cx = (left + right) / 2f;\n            float cy = height / 2f;\n            float eyeW = right - left;\n\n            // After the +/-90 degree panel correction the usable virtual viewport is height x eyeW.\n            float viewportW = height;\n            float viewportH = eyeW;\n\n            c.save();\n            c.clipRect(left, 0, right, height);\n            c.rotate(rotation, cx, cy);\n\n            float headX = 0f, headY = 0f, headRoll = 0f;\n            if (vrWorldLocked && calibrated) {\n                // A world-fixed plane moves opposite to head rotation. Keep translation bounded so HUD stays reachable.\n                headX = (float) clamp((-yawDeg / 55.0) * viewportW * 0.30, -viewportW * 0.30, viewportW * 0.30);\n                headY = (float) clamp((pitchDeg / 40.0) * viewportH * 0.30, -viewportH * 0.30, viewportH * 0.30);\n                headRoll = (float) clamp(-rollDeg, -35.0, 35.0);\n            }\n\n            float manualX = vrOffsetX * viewportW;\n            float manualY = vrOffsetY * viewportH;\n\n            // Crossed binocular disparity: left image shifts right, right image shifts left.\n            // This makes the duplicated 2D phone image fuse as a single virtual plane at finite depth.\n            float stereo = viewportW * vrStereoDepth * (leftEye ? 1f : -1f);\n\n            float screenCx = cx + manualX + headX + stereo;\n            float screenCy = cy + manualY + headY;\n            float boxW = viewportW * vrScreenScale;\n            float boxH = viewportH * vrScreenScale;\n\n            if (headRoll != 0f) c.rotate(headRoll, screenCx, screenCy);\n            dst.set(screenCx - boxW / 2f, screenCy - boxH / 2f, screenCx + boxW / 2f, screenCy + boxH / 2f);\n            boolean drawn = ScreenCaptureService.drawLatestFrame(c, dst, paint);\n            if (drawn) c.drawRoundRect(dst, 8f, 8f, framePaint);\n            c.restore();\n            return drawn;\n        }\n    }'''
replace_once(old_view, new_view, 'VR screen mirror view')

path.write_text(s, encoding='utf-8')
print('V1.0 VR gaming-screen patch applied successfully')
